import torch, b200probe as bp, statistics
SRC = r'''
__device__ __forceinline__ unsigned sa(const void* p){ return (unsigned)__cvta_generic_to_shared(p); }
__device__ __forceinline__ void mb_init(unsigned long long* b, unsigned c){ asm volatile("mbarrier.init.shared::cta.b64 [%0], %1;" :: "r"(sa(b)), "r"(c)); }
__device__ __forceinline__ void mb_expect(unsigned long long* b, unsigned tx){ asm volatile("mbarrier.arrive.expect_tx.shared::cta.b64 _, [%0], %1;" :: "r"(sa(b)), "r"(tx) : "memory"); }
__device__ __forceinline__ void bulk(void* dst, const void* src, unsigned bytes, unsigned long long* b){
  asm volatile("cp.async.bulk.shared::cluster.global.mbarrier::complete_tx::bytes [%0], [%1], %2, [%3];" :: "r"(sa(dst)), "l"(src), "r"(bytes), "r"(sa(b)) : "memory"); }
__device__ __forceinline__ void mb_wait(unsigned long long* b, unsigned ph){
  asm volatile("{\n .reg .pred p;\n W: mbarrier.try_wait.parity.shared::cta.b64 p, [%0], %1;\n @!p bra W;\n}" :: "r"(sa(b)), "r"(ph) : "memory"); }
__device__ __forceinline__ unsigned long long gt(){ unsigned long long t; asm volatile("mov.u64 %0, %%globaltimer;" : "=l"(t)); return t; }
__device__ void gsync(unsigned* bar, unsigned nb){
  __syncthreads();
  if (threadIdx.x == 0) {
    volatile unsigned* gen = bar + 1;
    unsigned g = *gen;
    __threadfence();
    if (atomicAdd(bar, 1) == nb - 1) { bar[0] = 0; __threadfence(); atomicAdd(bar + 1, 1); }
    else { while (*gen == g) {} }
    __threadfence();
  }
  __syncthreads();
}
#define S 5
#define CH 32768
__device__ unsigned ingest(char* ring, unsigned long long* full, unsigned it, const char* src, int bytes){
  int n = (bytes + CH - 1) / CH;
  if (threadIdx.x == 0) for (int i = 0; i < n && i < S; i++) { unsigned s = (it + i) % S; int b = min(CH, bytes - i*CH);
     mb_expect(full + s, b); bulk(ring + s*CH, src + (size_t)i*CH, b, full + s); }
  for (int i = 0; i < n; i++) { unsigned s = (it + i) % S; mb_wait(full + s, ((it + i) / S) & 1); __syncthreads();
     if (threadIdx.x == 0 && i + S < n) { int j = i + S; int b = min(CH, bytes - j*CH); mb_expect(full + s, b); bulk(ring + s*CH, src + (size_t)j*CH, b, full + s); } }
  return it + n;
}
extern "C" __global__ void __launch_bounds__(512,1) stub(const char* w1, const char* w2, const char* xin, const char* act, float* out, unsigned* bar,
  unsigned long long* st, int convb, int g1w, int g1a, int g2w, int g2a, int nred, int ns1, int ns2, int pref, int nouts, int mask) {
  extern __shared__ __align__(128) char sm[];
  __shared__ unsigned long long full[S]; __shared__ unsigned long long cb;
  int cta = blockIdx.x, P = gridDim.x;
  unsigned long long t0 = gt();
  if (threadIdx.x == 0) { for (int i = 0; i < S; i++) mb_init(full + i, 1); mb_init(&cb, 1); asm volatile("fence.mbarrier_init.release.cluster;"); }
  __syncthreads();
  char* ring = sm; char* cv = sm + S*CH;
  if (mask & 1) { if (threadIdx.x == 0) { mb_expect(&cb, convb); bulk(cv, xin + (size_t)cta * convb, convb, &cb); }
    mb_wait(&cb, 0);
    const float4* s4 = (const float4*)cv; float4* o4 = (float4*)(out + (size_t)cta * (pref/4));
    for (int i = threadIdx.x; i < pref/16; i += 512) { float4 v = s4[i % (convb/16)]; o4[i] = v; } }
  unsigned long long t1 = gt();
  gsync(bar, P);
  unsigned long long t2 = gt();
  unsigned it = 0;
  if (mask & 2) { it = ingest(ring, full, it, w1 + (size_t)(cta % ns1) * g1w, g1w); it = ingest(ring, full, it, act + (size_t)(cta / ns1) * g1a, g1a); }
  unsigned long long t3 = gt();
  gsync(bar, P);
  unsigned long long t4 = gt();
  if (mask & 4) { it = ingest(ring, full, it, w2 + (size_t)(cta % ns2) * g2w, g2w); it = ingest(ring, full, it, act + (size_t)(cta / ns2) * g2a, g2a); }
  unsigned long long t5 = gt();
  if (mask & 8) { for (int i = threadIdx.x; i < nred; i += 512) atomicAdd(out + ((size_t)cta * 7919 + (size_t)i * 33) % nouts, 1e-9f); }
  __syncthreads();
  unsigned long long t6 = gt();
  if (threadIdx.x == 0) { unsigned long long* p = st + cta * 8; p[0]=t0; p[1]=t1; p[2]=t2; p[3]=t3; p[4]=t4; p[5]=t5; p[6]=t6; }
}
'''
k = bp.cuda_kernel(SRC, "stub")
SMEM = 5*32768 + 100000
k.set_smem(SMEM)
w1 = torch.randn(3072*768, device="cuda"); w2 = torch.randn(3072*768, device="cuda")
xin = torch.randn(32*768*49 + 1<<20, device="cuda"); act = torch.randn(8<<20, device="cuda")
bar = torch.zeros(2, dtype=torch.int32, device="cuda"); st = torch.zeros(128*8, dtype=torch.int64, device="cuda")
rows = {  # convb, g1w, g1a, g2w, g2a, nred, ns1, ns2, pref, nouts
 "2,768": (6272, 73728, 208896, 73728, 104448, 4704, 128, 128, 2352, 98*768),
 "8,768": (12544, 294912, 208896, 294912, 208896, 9408, 32, 32, 9408, 392*768),
 "16,768": (18816, 294912, 405504, 294912, 405504, 18816, 32, 32, 18816, 784*768),
 "32,768": (37632, 589824, 811008, 589824, 811008, 18816, 16, 16, 37632, 1568*768),
 "8,384": (25088, 147456, 165888, 147456, 165888, 18816, 16, 16, 18816, 1568*384),
 "16,384": (50176, 294912, 331776, 294912, 331776, 18816, 8, 8, 37632, 3136*384),
}
out = torch.zeros(4<<20, device="cuda")
for name, r in rows.items():
  res = []
  for mask in (0, 1, 3, 7, 15):
    def fn(w1, w2, xin, act, out): k((128,), (512,), w1, w2, xin, act, out, bar, st, *r[:9], r[9], mask, smem=SMEM)
    res.append(bp.harness_time(fn, inputs=[w1, w2, xin, act], outputs=[out]))
  # stamps of last full run
  s = st.view(128, 8).cpu().double()
  t0 = s[:, 0].min()
  ph = [statistics.median(((s[:, j] - t0) / 1000).tolist()) for j in range(1, 7)]
  print(name, "harness us mask0/conv/+G1/+G2/+red:", [round(v, 1) for v in res], "stamps med us:", [round(v, 2) for v in ph])

