    mb_wait(&cb, 0);
    const float4* s4 = (const float4*)cv; float4* o4 = (float4*)(out + (size_t)cta * (pref/4));
    for (int i = threadIdx.x; i < pref/16; i += 512) { float4 v = s4[i % (convb/16)]; o4[i] = v; } }
  unsigned long long t1 = gt();
