SRC = r'''
__device__ __forceinline__ unsigned long long gt(){ unsigned long long t; asm volatile("mov.u64 %0, %%globaltimer;" : "=l"(t)); return t; }
extern "C" __global__ void __launch_bounds__(512,1) red(float* out, unsigned long long* st, int nred, int ks, int nouts, int v4) {
  int cta = blockIdx.x;
  unsigned long long t0 = gt();
  size_t base = ((size_t)(cta / ks) * nred) % nouts;
  if (v4) { for (int i = threadIdx.x; i < nred/4; i += 512) { float* p = out + (base + 4*(size_t)i) % nouts;
      asm volatile("red.global.add.v4.f32 [%0], {%1,%2,%3,%4};" :: "l"(p), "f"(1e-9f), "f"(1e-9f), "f"(1e-9f), "f"(1e-9f) : "memory"); } }
  else { for (int i = threadIdx.x; i < nred; i += 512) atomicAdd(out + (base + i) % nouts, 1e-9f); }
  __syncthreads();
  if (threadIdx.x == 0) { st[cta*2] = t0; st[cta*2+1] = gt(); }
}
'''
k = bp.cuda_kernel(SRC, "red")
st = torch.zeros(256, dtype=torch.int64, device="cuda")
out = torch.zeros(4<<20, device="cuda")
for name, nred, ks, nouts in [("2,768",4704,8,98*768),("8,768",9408,4,392*768),("16,768",18816,4,784*768),("32,768",18816,2,1568*768),("16,384",18816,2,3136*384)]:
  r = []
  for v4 in (0,1):
    def fn(out): k((128,), (512,), out, st, nred, ks, nouts, v4)
    r.append(bp.harness_time(fn, inputs=[], outputs=[out]))
  print(name, "scalar/v4 us:", [round(v,1) for v in r], "MB", nred*128*4/1e6)

