  const size_t ringW = (size_t)WS_S * WS_WSTAGE; const size_t ringA = (size_t)WS_S * 32 * pl.Tpp * 2;
  pl.o_A = (int)ringW; pl.o_Bh = (int)(ringW + ringA);
  const int bhrows = (r.NI * r.CS > pl.NB1) ? r.NI * r.CS : pl.NB1;
  const size_t bhEnd = (size_t)pl.o_Bh + (size_t)bhrows * BH_LD * 2;
  pl.o_cx = WS_WPRE * WS_WSTAGE; pl.o_cw = pl.o_cx + pl.UPC * 32 * pl.HW * 4; pl.o_cd = pl.o_cw + pl.UPC * 32 * 49 * 4;
  const size_t convEnd = (size_t)pl.o_cd + (size_t)pl.UPC * 32 * pl.HW * 4;
  const size_t raw = (size_t)pl.NB1 * (pl.Tp + 4) * 4; pl.o_hst = (int)ws_al(raw, 128);
  const size_t g1End = (size_t)pl.o_hst + (size_t)pl.NB1 * pl.Tpp * 2; const size_t g2End = (size_t)r.NI * r.CS * pl.HW * 4;
  size_t R = bhEnd; if (convEnd > R) R = convEnd; if (g1End > R) R = g1End; if (g2End > R) R = g2End;
  pl.o_tab = (int)ws_al(R, 1024);
  const size_t tab = (size_t)(4 * C + r.BN + 2 * pl.KSL + r.NI * pl.KSL + 2 * pl.Tp + 3 * 96 + 16) * 4 + (WS_S + 2) * 8;
  pl.smem = (int)(pl.o_tab + tab + 1024);
  return pl.smem <= 227 * 1024;
}
extern "C" long long ws_workspace_bytes(int B, int C, int H, int W) { WSPlan pl; if (!ws_plan(B, C, H, W, pl)) return 0; return (long long)pl.ws_bytes; }
static bool encode_w(CUtensorMap* m, const float* base, int rows, int cols, int box_rows) {
  const cuuint64_t dims[2] = {(cuuint64_t)cols, (cuuint64_t)rows}; const cuuint64_t strides[1] = {(cuuint64_t)cols * 4};
  const cuuint32_t box[2] = {32u, (cuuint32_t)box_rows}; const cuuint32_t estr[2] = {1u, 1u};
  return cuTensorMapEncodeTiled(m, CU_TENSOR_MAP_DATA_TYPE_FLOAT32, 2, (void*)base, dims, strides, box, estr, CU_TENSOR_MAP_INTERLEAVE_NONE, CU_TENSOR_MAP_SWIZZLE_128B, CU_TENSOR_MAP_L2_PROMOTION_L2_256B, CU_TENSOR_MAP_FLOAT_OOB_FILL_NONE) == CUDA_SUCCESS;
}
extern "C" const char* ws_launch(const WSArgs* a, void* stream_v) {
  static bool attr_done = false;
  if (!attr_done) {
    cudaFuncSetAttribute(ws_kernel<0>, cudaFuncAttributeMaxDynamicSharedMemorySize, 227 * 1024);
    cudaFuncSetAttribute(ws_kernel<1>, cudaFuncAttributeMaxDynamicSharedMemorySize, 227 * 1024);
    cudaFuncSetAttribute(ws_kernel<2>, cudaFuncAttributeMaxDynamicSharedMemorySize, 227 * 1024);
    cudaFuncSetAttribute(ws_kernel<3>, cudaFuncAttributeMaxDynamicSharedMemorySize, 227 * 1024);
    attr_done = true;
  }
  WSPlan pl; if (!ws_plan(a->B, a->C, a->H, a->W, pl)) return "unsupported";
  WSP p; memset(&p, 0, sizeof(p));
  if (!encode_w(&p.tm1, a->w1, pl.C4, a->C, pl.NB1)) return "tm1";
  if (!encode_w(&p.tm2, a->w2, a->C, pl.C4, pl.r.CS)) return "tm2";
  char* wsb = (char*)a->ws;
  p.x = a->x; p.dww = a->dww; p.dwb = a->dwb; p.lnw = a->lnw; p.lnb = a->lnb; p.b1 = a->b1; p.gw = a->gw; p.gb = a->gb; p.b2 = a->b2; p.out = a->out;
  p.d16 = (__half*)(wsb + pl.o_d16); p.part = (float*)(wsb + pl.o_part); p.hid = (__half*)(wsb + pl.o_hid); p.gf = (float*)(wsb + pl.o_gf); p.gpart = (float*)(wsb + pl.o_gpart);
  p.stamps = a->stamps; p.dbg = a->dbg;
  p.B = a->B; p.C = a->C; p.H = a->H; p.W = a->W; p.HW = pl.HW; p.C4 = pl.C4; p.G = pl.G; p.units = pl.units;
  p.NI = pl.r.NI; p.HWp = pl.HWp; p.Tp = pl.Tp; p.Tpp = pl.Tpp; p.MT = pl.Tp / 16; p.MPI = pl.HWp / 16;
  p.BN = pl.r.BN; p.NB1 = pl.NB1; p.NS1 = pl.NS1; p.npass = pl.r.npass; p.nk1 = a->C / 32;
  p.CS = pl.r.CS; p.KS = pl.r.KS; p.KSL = pl.KSL; p.NCS = pl.NCS; p.nk2 = pl.KSL / 32;
  p.eps = a->eps; p.ln_eps = a->ln_eps;
  p.o_A = pl.o_A; p.o_Bh = pl.o_Bh; p.o_cx = pl.o_cx; p.o_cw = pl.o_cw; p.o_cd = pl.o_cd; p.o_hst = pl.o_hst; p.o_tab = pl.o_tab;
  void* args[] = {&p};
  const void* fn = pl.r.cfg == 0 ? (const void*)ws_kernel<0> : pl.r.cfg == 1 ? (const void*)ws_kernel<1> : pl.r.cfg == 2 ? (const void*)ws_kernel<2> : (const void*)ws_kernel<3>;
  cudaError_t e = cudaLaunchCooperativeKernel(fn, dim3(pl.P), dim3(WS_NT), args, (size_t)pl.smem, (cudaStream_t)stream_v);
  if (e != cudaSuccess) return cudaGetErrorString(e);
  return nullptr;
}
'''
d = tempfile.mkdtemp()
open(d + "/k.cu", "w").write(SRC)
r = subprocess.run(f"nvcc -O3 --use_fast_math -std=c++17 -arch=sm_100a -shared -Xcompiler -fPIC {d}/k.cu -lcuda -o {d}/k.so", shell=True, capture_output=True, text=True)
print("\n".join(l for l in r.stderr.splitlines() if "error" in l)[:1500])
lib = ctypes.CDLL(d + "/k.so")
lib.ws_launch.restype = ctypes.c_char_p
lib.ws_workspace_bytes.restype = ctypes.c_longlong
class WSArgs(ctypes.Structure):
    _fields_ = [(n, ctypes.c_void_p) for n in ["x","dww","dwb","lnw","lnb","w1","b1","gw","gb","w2","b2","out","ws","stamps"]] + \
               [(n, ctypes.c_int) for n in ["B","C","H","W"]] + [("eps", ctypes.c_float), ("ln_eps", ctypes.c_float), ("dbg", ctypes.c_int)]
stamps = torch.zeros(148*128, dtype=torch.int64, device="cuda")
names = {7:"vec",8:"convIn",11:"convDone",1:"Adone",2:"sync1",12:"muRs",9:"G1main0",13:"raw0",14:"gelu0",15:"hid0",3:"G1done",4:"sync2",10:"Cprol",5:"G2main",6:"end"}
for (B,C,H,W) in [(2,768,7,7),(32,768,7,7)]:
    x = torch.randn(B,C,H,W, device="cuda")
    dww = torch.randn(C,1,7,7, device="cuda")/7**0.5; dwb = torch.randn(C, device="cuda")
    lnw = torch.ones(C, device="cuda"); lnb = torch.zeros(C, device="cuda")
    w1 = torch.randn(4*C, C, device="cuda")/C**0.5; b1 = torch.randn(4*C, device="cuda")
    gw = torch.randn(1,1,1,4*C, device="cuda")/(4*C)**0.5; gb = torch.randn(1,1,1,4*C, device="cuda")
    w2 = torch.randn(C, 4*C, device="cuda")/(4*C)**0.5; b2 = torch.randn(C, device="cuda")
    out = torch.zeros_like(x)
    ws = torch.empty(lib.ws_workspace_bytes(B,C,H,W), dtype=torch.uint8, device="cuda")
    ins = [x, dww, dwb, lnw, lnb, w1, b1, gw, gb, w2, b2]
    def launch(st, dbg):
        a = WSArgs(*[t.data_ptr() for t in ins + [out, ws]], st.data_ptr(), B, C, H, W, 1e-6, 1e-6, dbg)
        e = lib.ws_launch(ctypes.byref(a), ctypes.c_void_p(torch.cuda.current_stream().cuda_stream))
        if e: raise RuntimeError(e)
    for dbg in (0, 8, 7):
        launch(stamps, dbg); torch.cuda.synchronize()
        bp.flush_l2(); launch(stamps, dbg); torch.cuda.synchronize()
        s = stamps.view(148,128)[:128].cpu().double(); t0 = s[:,0].min()
        med = lambda k: statistics.median(((s[:,k]-t0)/1000).tolist())
        line = "  ".join(f"{names[k]} {med(k):.1f}" for k in [7,8,11,1,2,12,9,13,14,15,3,4,10,5,6])
        g1 = [med(32+j) for j in range(8)]; g2 = [med(80+j) for j in range(8)]
        print((B,C,H,W), "dbg", dbg, "|", line)
        print("   G1 chunk waits:", [round(v,2) for v in g1], " G2:", [round(v,2) for v in g2])

